      it('attached top right, orientation left', function() {

        // when
        var connection = connect('BoundaryEvent_TopRight', 'Task_Left');

        // then
        expect(connection).to.have.waypoints([
          { original: { x: 650, y: 300 }, x: 650, y: 282 },
          { x: 650, y: 262 },
          { x: 50, y: 262 },
          { original: { x: 50, y: 390 }, x: 50, y: 350 }
